mapper.update:
UPDATE conversations
SET title = #{title},
    updated_at = NOW()
WHERE id = #{conversationId}
  AND user_id = #{userId}

UPDATE conversations
SET config = #{config, typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},
    updated_at = NOW()
WHERE id = #{conversationId}
  AND user_id = #{userId}
  AND COALESCE(message_count, 0) = 0
